function startDodge(){mode='dodge';attackTimer=0;playTime=0;heart.x=480;heart.y=390;bullets=[];bones=[];}
function beginBreak(){mode='break';collected=0;heart.x=480;heart.y=390;bullets=[];fragments=[{x:310,y:345,id:0,got:false},{x:640,y:360,id:1,got:false},{x:480,y:456,id:2,got:false}];playTime=0;}
function afterDodge(){turn++;if(turn>=2)phase=2;if(hp<=0){ending=0;mode='ending'}else mode='menu'}
function doAttack(){let delta=Math.abs(attackTimer-attackTarget);attackResult=delta<24?3:delta<65?2:1;score+=attackResult*17;flash=attackResult===3?8:3;shake=attackResult===3?6:2;attackTimer=0;
if(turn===2&&phase===2){beginBreak();return}
if(turn>=4){ending=1;mode='ending';return}startDodge();}
function choose(){if(mode==='title'){mode='intro';return}if(mode==='intro'){dialogue++;if(dialogue>=3){dialogue=0;mode='menu'}return}
if(mode==='menu'){if(menu===0){mode='attack';attackTimer=173;attackTarget=320+Math.random()*320;return}if(menu===1){mode='intro';dialogue=0;lines[0]="he's got no patience for small talk.";lines[1]="you already know what comes next.";lines[2]="back to it, then.";return}if(menu===2){hp=Math.min(maxHp,hp+6);mode='intro';dialogue=0;lines[0]="you ate a butterscotch snack.";lines[1]="your HP was restored a little.";lines[2]="sans watches you quietly.";return}if(menu===3){ending=1;mode='ending';return}}
if(mode==='attack')doAttack();else if(mode==='break'&&collected===3){mode='repair';restoreTimer=75;flash=5}}
function reset(){mode='title';hp=maxHp=20;turn=0;phase=1;menu=0;dialogue=0;ending=0;bullets=[];fragments=[];collected=0;lines[0]="heya. you made it all this way.";lines[1]="i'm impressed. really.";lines[2]="let's see if you can keep it up."}
function keyDown(e){let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' ','enter'].includes(k))e.preventDefault();keys[k]=true;if(e.repeat)return;
if(k==='z'||k===' '||k==='enter'){if(mode==='ending'){reset();return}choose()}
if(k==='x'||k==='escape'){if(mode==='intro'&&dialogue>0){mode='menu';dialogue=0}else if(mode==='menu')menu=0}
if(mode==='menu'){if(k==='arrowleft'||k==='a')menu=(menu+3)%4;if(k==='arrowright'||k==='d')menu=(menu+1)%4}
}
function keyUp(e){keys[e.key.toLowerCase()]=false}
window.addEventListener('keydown',keyDown);window.addEventListener('keyup',keyUp);window.addEventListener('blur',()=>{for(const k in keys)keys[k]=false});
document.querySelectorAll('.mobile-controls button').forEach(btn=>{const key=btn.dataset.key;btn.addEventListener('pointerdown',e=>{e.preventDefault();keys[key.toLowerCase()]=true;if(key==='z')choose()});for(const ev of ['pointerup','pointercancel','pointerleave'])btn.addEventListener(ev,()=>keys[key.toLowerCase()]=false)});
function addHazard(){let left=arena.x+14,right=arena.x+arena.w-14,top=arena.y+12,bottom=arena.y+arena.h-12;let pattern=(Math.floor(playTime/90)+turn)%4;
if(pattern===0){let y=top+Math.random()*(bottom-top);bullets.push({type:'bone',x:right,y,w:34,h:8,vx:-4.3-turn*.18,vy:0})}
else if(pattern===1){let x=left+Math.random()*(right-left);bullets.push({type:'bone',x,y:top,w:8,h:34,vx:0,vy:3.7+turn*.12})}
else if(pattern===2){bullets.push({type:'blaster',x:right-8,y:top+20+Math.random()*(bottom-top-40),vx:-2.2,beam:0,age:0})}
else{let x=left+Math.random()*(right-left),y=top;bullets.push({type:'orb',x,y,r:6,color:turn%2?colors.cyan:'#ffd05c',vx:(heart.x-x)*.012,vy:3.1})}}
function updateDodge(){playTime++;if(playTime%42===0)addHazard();let speed=3.3;let dx=((keys.arrowright||keys.d)?1:0)-((keys.arrowleft||keys.a)?1:0),dy=((keys.arrowdown||keys.s)?1:0)-((keys.arrowup||keys.w)?1:0);if(dx&&dy){dx*=.707;dy*=.707}heart.x=Math.max(arena.x+17,Math.min(arena.x+arena.w-17,heart.x+dx*speed));heart.y=Math.max(arena.y+17,Math.min(arena.y+arena.h-17,heart.y+dy*speed));
if(invuln>0)invuln--;for(let i=bullets.length-1;i>=0;i--){let b=bullets[i];b.x+=b.vx||0;b.y+=b.vy||0;if(b.type==='blaster'){b.age++;if(b.age===35)b.beam=18;if(b.age>45)b.beam=18;if(b.age>58)b.beam=0;if(b.age>90){bullets.splice(i,1);continue}}else if(b.x<arena.x-45||b.x>arena.x+arena.w+45||b.y>arena.y+arena.h+45){bullets.splice(i,1);continue}
let hit=false;if(b.type==='bone')hit=heart.x>b.x-10&&heart.x<b.x+b.w+8&&heart.y>b.y-9&&heart.y<b.y+b.h+9;else if(b.type==='blaster'&&b.beam)hit=Math.abs(heart.y-b.y)<12;else hit=Math.hypot(heart.x-b.x,heart.y-b.y)<(b.r||7)+8;if(hit&&invuln===0){hp=Math.max(0,hp-2);invuln=42;shake=4;flash=3}}
if(playTime>430||hp<=0)afterDodge();}
function updateBreak(){playTime++;let speed=3.1,dx=((keys.arrowright||keys.d)?1:0)-((keys.arrowleft||keys.a)?1:0),dy=((keys.arrowdown||keys.s)?1:0)-((keys.arrowup||keys.w)?1:0);if(dx&&dy){dx*=.707;dy*=.707}heart.x=Math.max(arena.x+18,Math.min(arena.x+arena.w-18,heart.x+dx*speed));heart.y=Math.max(arena.y+18,Math.min(arena.y+arena.h-18,heart.y+dy*speed));
for(let f of fragments){if(!f.got&&Math.hypot(heart.x-f.x,heart.y-f.y)<25){f.got=true;collected++;flash=4;score+=50}}
if(playTime%76===0){let x=arena.x+30+Math.random()*(arena.w-60);bullets.push({type:'bone',x:arena.x+arena.w-8,y:arena.y+24+Math.random()*(arena.h-48),w:25,h:7,vx:-3.3,vy:0})}
for(let i=bullets.length-1;i>=0;i--){let b=bullets[i];b.x+=b.vx; if(b.x<arena.x-35)bullets.splice(i,1);else if(invuln===0&&heart.x>b.x-9&&heart.x<b.x+b.w+5&&Math.abs(heart.y-b.y)<13){hp=Math.max(1,hp-1);invuln=48}}
if(invuln>0)invuln--;if(hp<=0){hp=1;}}
function update(){tick++;if(flash>0)flash--;if(mode==='attack'){attackTimer+=8.2;if(attackTimer>787)attackTimer=173}
if(mode==='dodge')updateDodge();if(mode==='break')updateBreak();if(mode==='repair'){restoreTimer--;if(restoreTimer<=0){mode='menu';turn=3;phase=2;bullets=[];}}
render();requestAnimationFrame(update)}
requestAnimationFrame(update);
})();
</script></body></html>

